"""
export_c_array.py - converts model/artifacts/model_quant.tflite into a C
header (model_data.h) embedding the model as a byte array, plus a second
header (model_params.h) with the normalization mean/std and the detection
threshold - exactly the pattern every TensorFlow Lite for Microcontrollers
example uses (historically produced by `xxd -i model.tflite`).

Usage:
    python model/export_c_array.py
"""
import json
import os

ARTIFACTS_DIR = os.path.join(os.path.dirname(__file__), "artifacts")


def to_c_array(data: bytes, var_name: str) -> str:
    lines = [
        "// Auto-generated by model/export_c_array.py - do not edit by hand.",
        "#pragma once",
        "",
        f"alignas(8) const unsigned char {var_name}[] = {{",
    ]
    for i in range(0, len(data), 12):
        chunk = data[i:i + 12]
        lines.append("    " + ", ".join(f"0x{b:02x}" for b in chunk) + ",")
    lines.append("};")
    lines.append(f"const unsigned int {var_name}_len = {len(data)};")
    return "\n".join(lines) + "\n"


def main():
    tflite_path = os.path.join(ARTIFACTS_DIR, "model_quant.tflite")
    with open(tflite_path, "rb") as f:
        model_bytes = f.read()

    model_header = to_c_array(model_bytes, "g_model_data")
    model_header_path = os.path.join(ARTIFACTS_DIR, "model_data.h")
    with open(model_header_path, "w") as f:
        f.write(model_header)
    print(f"Wrote {model_header_path} ({len(model_bytes)} bytes embedded)")

    with open(os.path.join(ARTIFACTS_DIR, "normalization.json")) as f:
        norm = json.load(f)
    with open(os.path.join(ARTIFACTS_DIR, "threshold_quant.json")) as f:
        thresh = json.load(f)

    params_header = f"""// Auto-generated by model/export_c_array.py - do not edit by hand.
#pragma once

constexpr float kNormalizationMean = {norm['mean']}f;
constexpr float kNormalizationStd  = {norm['std']}f;
constexpr int   kWindowSize        = {norm['window_size']};
constexpr float kAnomalyThreshold  = {thresh['threshold']}f;
"""
    params_header_path = os.path.join(ARTIFACTS_DIR, "model_params.h")
    with open(params_header_path, "w") as f:
        f.write(params_header)
    print(f"Wrote {params_header_path}")


if __name__ == "__main__":
    main()
